import { toNextJsHandler } from "better-auth/next-js";
import { auth } from "@/lib/auth";

export const { GET, POST } = toNextJsHandler(auth);

"use client";

import { createAuthClient } from "better-auth/react";

export const authClient = createAuthClient({
  baseURL: process.env.NEXT_PUBLIC_APP_URL,
});

import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { bearer } from "better-auth/plugins/bearer";
import { db } from "@/lib/db";

export const auth = betterAuth({
  appName: "replay.md",
  database: drizzleAdapter(db, {
    provider: "pg",
  }),
  trustedOrigins: [
    process.env.NEXT_PUBLIC_APP_URL!,
  ],
  socialProviders: {
    github: {
      clientId: process.env.GITHUB_CLIENT_ID!,
      clientSecret: process.env.GITHUB_CLIENT_SECRET!,
    },
    google: {
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
    },
  },
  plugins: [bearer()],
  user: {
    additionalFields: {
      username: {
        type: "string",
        required: false,
        unique: true,
        input: true,
      },
    },
  },
  session: {
    expiresIn: 60 * 60 * 24 * 30, // 30 days
    updateAge: 60 * 60 * 24, // refresh daily
  },
  rateLimit: {
    enabled: true,
    window: 10,
    max: 100,
    customRules: {
      "/api/auth/sign-in/*": { window: 60, max: 10 },
      "/api/auth/sign-up/*": { window: 60, max: 5 },
    },
  },
  advanced: {
    database: {
      generateId: "uuid",
    },
  },
});

export type Session = typeof auth.$Infer.Session;
export type User = typeof auth.$Infer.Session.user;

import { NextResponse } from "next/server";
import { auth, type Session } from "@/lib/auth";

const UNAUTHORIZED = NextResponse.json(
  { error: "Unauthorized" },
  { status: 401 }
);

/**
 * Minimum CLI version the server will accept.
 * Bump this when a breaking change requires clients to update.
 */
const MIN_CLI_VERSION = "0.3.0";

/**
 * Require authentication. Returns the session or a 401 NextResponse.
 *
 * Usage in route handlers:
 * ```ts
 * const [session, errorResponse] = await requireAuth(request);
 * if (errorResponse) return errorResponse;
 * // session is guaranteed non-null here
 * ```
 */
export async function requireAuth(
  request: Request
): Promise<[Session, null] | [null, NextResponse]> {
  const session = await auth.api.getSession({
    headers: request.headers,
  });

  if (!session) {
    return [null, UNAUTHORIZED];
  }

  return [session, null];
}

/**
 * Optionally get the session. Returns null if not authenticated.
 */
export async function getOptionalSession(
  request: Request
): Promise<Session | null> {
  return auth.api.getSession({
    headers: request.headers,
  });
}

/**
 * Validate that a redirect URI is a safe localhost URL (for CLI auth flow).
 * Only allows http://localhost:* and http://127.0.0.1:*
 */
export function isLocalhostRedirect(uri: string): boolean {
  try {
    const url = new URL(uri);
    const hostname = url.hostname;
    return (
      (hostname === "localhost" || hostname === "127.0.0.1") &&
      url.protocol === "http:"
    );
  } catch {
    return false;
  }
}

/**
 * Validate that a request comes from the CLI.
 * Checks for the X-Replay-Client header.
 */
export function isCliRequest(request: Request): boolean {
  return request.headers.get("x-replay-client") === "cli";
}

/**
 * Compare two semver version strings (x.y.z).
 * Returns negative if a < b, 0 if equal, positive if a > b.
 */
function compareSemver(a: string, b: string): number {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    const diff = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (diff !== 0) return diff;
  }
  return 0;
}

/**
 * Check that a CLI request meets the minimum version requirement.
 * Returns a 426 NextResponse if the client version is missing or too old,
 * or null if the version is acceptable.
 *
 * Call this on routes that require `isCliRequest(request) === true`.
 */
export function checkCliVersion(request: Request): NextResponse | null {
  const clientVersion = request.headers.get("x-client-version");

  if (!clientVersion || compareSemver(clientVersion, MIN_CLI_VERSION) < 0) {
    return NextResponse.json(
      {
        error: "client_upgrade_required",
        min_version: MIN_CLI_VERSION,
        message: `Your CLI is outdated. Please update to v${MIN_CLI_VERSION} or later.`,
      },
      { status: 426 }
    );
  }

  return null;
}

import { relations, sql } from "drizzle-orm";
import {
  pgTable,
  text,
  timestamp,
  boolean,
  uuid,
  index,
} from "drizzle-orm/pg-core";

export const user = pgTable("user", {
  id: uuid("id")
    .default(sql`pg_catalog.gen_random_uuid()`)
    .primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => /* @__PURE__ */ new Date())
    .notNull(),
  username: text("username").unique(),
});

export const session = pgTable(
  "session",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: uuid("id")
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => /* @__PURE__ */ new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "bunVersion": "1.x"
}

"use client";

import {
  startTransition,
  useCallback,
  useDeferredValue,
  useEffect,
  useRef,
  useState,
} from "react";
import {
  init,
  sync,
  search as searchIndex,
  indexedCount,
  type GroupedSearchResult,
} from "./index";

interface UseThreadSearch {
  /** Search results grouped by thread, each with matching message snippets */
  results: GroupedSearchResult[];
  syncing: boolean;
  isSearching: boolean;
  totalIndexed: number;
  resync: () => Promise<void>;
}

type SearchIdleWindow = Window & {
  requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number;
  cancelIdleCallback?: (handle: number) => void;
};

export function useThreadSearch(query: string): UseThreadSearch {
  const [results, setResults] = useState<GroupedSearchResult[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [totalIndexed, setTotalIndexed] = useState(0);
  const [ready, setReady] = useState(false);
  const mountedRef = useRef(true);
  const initTaskRef = useRef<Promise<void> | null>(null);
  const deferredQuery = useDeferredValue(query);

  const ensureInitialized = useCallback(() => {
    if (initTaskRef.current) {
      return initTaskRef.current;
    }

    initTaskRef.current = (async () => {
      await init();
      if (!mountedRef.current) return;
      setTotalIndexed(indexedCount());
      setReady(true);
    })().catch((error) => {
      initTaskRef.current = null;
      throw error;
    });

    return initTaskRef.current;
  }, []);

  const syncIndex = useCallback(async () => {
    setSyncing(true);
    try {
      await ensureInitialized();
      await sync();
      if (!mountedRef.current) return;
      setTotalIndexed(indexedCount());
    } catch (err) {
      console.error("[search] sync error:", err);
    } finally {
      if (mountedRef.current) {
        setSyncing(false);
      }
    }
  }, [ensureInitialized]);

  useEffect(() => {
    return () => {
      mountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    let timeoutId: number | null = null;
    let idleId: number | null = null;
    const idleWindow = window as SearchIdleWindow;

    const bootstrap = () => {
      void ensureInitialized()
        .then(() => syncIndex())
        .catch((error) => {
          console.error("[search] init error:", error);
        });
    };

    if (typeof idleWindow.requestIdleCallback === "function") {
      idleId = idleWindow.requestIdleCallback(bootstrap, { timeout: 1500 });
    } else {
      timeoutId = window.setTimeout(bootstrap, 0);
    }

    return () => {
      if (idleId !== null && typeof idleWindow.cancelIdleCallback === "function") {
        idleWindow.cancelIdleCallback(idleId);
      }
      if (timeoutId !== null) {
        window.clearTimeout(timeoutId);
      }
    };
  }, [ensureInitialized, syncIndex]);

  useEffect(() => {
    if (!ready || !deferredQuery.trim()) {
      if (deferredQuery.trim()) {
        void ensureInitialized();
      }
      setResults([]);
      return;
    }

    startTransition(() => {
      setResults(searchIndex(deferredQuery));
    });
  }, [deferredQuery, ensureInitialized, ready]);

  const resync = useCallback(async () => {
    await syncIndex();
    if (query.trim()) {
      startTransition(() => {
        setResults(searchIndex(query));
      });
    }
  }, [query, syncIndex]);

  return {
    results,
    syncing,
    isSearching: query.trim().length > 0,
    totalIndexed,
    resync,
  };
}

"use client";

import Link from "next/link";
import posthog from "posthog-js";
import type { GroupedSearchResult } from "@/lib/search/index";

interface SearchResultsProps {
  results: GroupedSearchResult[];
  query: string;
}

function highlightMatch(text: string, query: string) {
  if (!query.trim()) return text;

  // Build regex from query words for highlighting
  const words = query
    .trim()
    .split(/\s+/)
    .filter((w) => w.length > 1)
    .map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (words.length === 0) return text;

  const regex = new RegExp(`(${words.join("|")})`, "gi");
  const parts = text.split(regex);

  return parts.map((part, i) =>
    i % 2 === 1 ? (
      <mark
        key={i}
        className="bg-accent/20 text-accent rounded-[2px] px-[2px] mx-[-2px]"
      >
        {part}
      </mark>
    ) : (
      part
    )
  );
}

export function SearchResults({ results, query }: SearchResultsProps) {
  if (results.length === 0) {
    return (
      <p className="text-[13px] text-fg-ghost py-8 text-center">
        No matches for &ldquo;{query}&rdquo;
      </p>
    );
  }

  function trackClick(slug: string, index: number) {
    posthog.capture("search_result_clicked", {
      query,
      result_thread_slug: slug,
      result_index: index,
    });
  }

  return (
    <div className="space-y-1">
      {results.map((group, groupIdx) => (
        <div
          key={group.threadId}
          className="border border-border rounded-[4px] overflow-hidden"
        >
          {/* Thread header */}
          <Link
            href={`/t/${group.slug}`}
            onClick={() => trackClick(group.slug, groupIdx)}
            className="flex items-center gap-2 border-b border-border bg-surface-raised px-4 py-2.5 transition-colors duration-150 hover:bg-surface-raised/80 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-accent focus-visible:ring-inset"
          >
            <span className="text-[13px] font-medium text-fg truncate">
              {group.title ?? "Untitled thread"}
            </span>
            <span className="ml-auto shrink-0 font-mono text-[11px] text-fg-ghost">
              {group.matches.length}{" "}
              {group.matches.length === 1 ? "match" : "matches"}
            </span>
          </Link>

          {/* Matching message snippets */}
          <div className="divide-y divide-border/50">
            {group.matches.slice(0, 5).map((match) => (
              <Link
                key={match.ordinal}
                href={`/t/${group.slug}#m${match.ordinal}`}
                onClick={() => trackClick(group.slug, groupIdx)}
                className="group flex gap-3 px-4 py-2 transition-colors duration-150 hover:bg-surface-raised/40 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-accent focus-visible:ring-inset"
              >
                <span className="shrink-0 font-mono text-[10px] text-fg-faint mt-[3px] w-14 text-right">
                  {match.role === "user" ? "you" : "agent"}
                </span>
                <p className="text-[12px] text-fg-muted leading-relaxed line-clamp-2 group-hover:text-fg transition-colors duration-150">
                  {highlightMatch(match.snippet, query)}
                </p>
              </Link>
            ))}
            {group.matches.length > 5 && (
              <Link
                href={`/t/${group.slug}`}
                onClick={() => trackClick(group.slug, groupIdx)}
                className="block px-4 py-1.5 text-[11px] text-fg-ghost transition-colors duration-150 hover:text-fg-muted focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-accent focus-visible:ring-inset"
              >
                +{group.matches.length - 5} more{" "}
                {group.matches.length - 5 === 1 ? "match" : "matches"}
              </Link>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Thread search engine — per-message indexing.
 *
 * Each message is individually indexed so search results can show
 * exactly which message matched with a surrounding snippet.
 *
 * Sync flow:
 *   1. Load threads + messages from IndexedDB → rebuild FlexSearch index
 *   2. Fetch /api/threads/sync?since=<lastSyncTs> for incremental updates
 *   3. Upsert into IndexedDB + FlexSearch
 *   4. Persist new syncTs
 */

import { Index as FlexIndex } from "flexsearch";
import {
  type StoredThread,
  type StoredMessage,
  getAllThreads,
  getAllMessages,
  putThreadsAndMessages,
  getSyncTs,
  setSyncTs,
} from "./db";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface SearchMatch {
  threadId: string;
  slug: string;
  title: string | null;
  agent: string;
  model: string | null;
  ordinal: number;
  role: string;
  snippet: string;
}

export interface GroupedSearchResult {
  threadId: string;
  slug: string;
  title: string | null;
  agent: string;
  model: string | null;
  matches: { ordinal: number; role: string; snippet: string }[];
}

// ---------------------------------------------------------------------------
// In-memory stores
// ---------------------------------------------------------------------------

/** Thread metadata by id */
const threadMap = new Map<string, StoredThread>();

/** Message lookup by numeric FlexSearch key */
const keyToMessage = new Map<number, StoredMessage>();

/** Map composite message key → numeric FlexSearch key */
const msgKeyToNum = new Map<string, number>();
let nextKey = 0;

const flexIndex = new FlexIndex({
  tokenize: "forward",
  cache: 100,
});
const INDEX_BATCH_SIZE = 250;

let initialized = false;
let initPromise: Promise<number> | null = null;

function getNumKey(compositeKey: string): number {
  let key = msgKeyToNum.get(compositeKey);
  if (key === undefined) {
    key = nextKey++;
    msgKeyToNum.set(compositeKey, key);
  }
  return key;
}

function indexMessage(msg: StoredMessage) {
  const numKey = getNumKey(msg.key);
  if (keyToMessage.has(numKey)) {
    flexIndex.update(numKey, msg.content);
  } else {
    flexIndex.add(numKey, msg.content);
  }
  keyToMessage.set(numKey, msg);
}

async function yieldToMainThread() {
  await new Promise<void>((resolve) => {
    if (typeof window !== "undefined" && "requestAnimationFrame" in window) {
      window.requestAnimationFrame(() => resolve());
      return;
    }

    setTimeout(resolve, 0);
  });
}

async function indexMessagesInBatches(messages: StoredMessage[]) {
  for (let index = 0; index < messages.length; index += INDEX_BATCH_SIZE) {
    const batch = messages.slice(index, index + INDEX_BATCH_SIZE);

    for (const message of batch) {
      indexMessage(message);
    }

    if (index + INDEX_BATCH_SIZE < messages.length) {
      await yieldToMainThread();
    }
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/** Initialize: load from IndexedDB and rebuild the in-memory index */
export async function init(): Promise<number> {
  if (initialized) {
    return threadMap.size;
  }

  if (initPromise) {
    return initPromise;
  }

  initPromise = (async () => {
    const [threads, messages] = await Promise.all([
      getAllThreads(),
      getAllMessages(),
    ]);

    for (const currentThread of threads) {
      threadMap.set(currentThread.id, currentThread);
    }

    await indexMessagesInBatches(messages);
    initialized = true;
    return threadMap.size;
  })().catch((error) => {
    initPromise = null;
    throw error;
  });

  return initPromise;
}

/** Sync with the server. Returns the number of new/updated threads. */
export async function sync(): Promise<number> {
  const since = await getSyncTs();

  // Skip if synced recently (avoid redundant requests on rapid navigation)
  if (since) {
    const age = Date.now() - new Date(since).getTime();
    if (age < 30_000) return 0;
  }

  const url = since
    ? `/api/threads/sync?since=${encodeURIComponent(since)}`
    : `/api/threads/sync`;

  const res = await fetch(url);
  if (!res.ok) throw new Error(`Sync failed: ${res.status}`);

  const data: {
    threads: (StoredThread & {
      messages: { ordinal: number; role: string; content: string }[];
    })[];
    syncTs: string;
  } = await res.json();

  if (data.threads.length > 0) {
    const storedThreads: StoredThread[] = [];
    const storedMessages: StoredMessage[] = [];

    for (const t of data.threads) {
      const { messages: msgs, ...threadData } = t;
      storedThreads.push(threadData);
      threadMap.set(t.id, threadData);

      for (const m of msgs) {
        const stored: StoredMessage = {
          key: `${t.id}:${m.ordinal}`,
          threadId: t.id,
          ordinal: m.ordinal,
          role: m.role,
          content: m.content,
        };
        storedMessages.push(stored);
      }
    }

    await indexMessagesInBatches(storedMessages);
    await putThreadsAndMessages(storedThreads, storedMessages);
  }

  await setSyncTs(data.syncTs);
  return data.threads.length;
}

/**
 * Extract a snippet around the first occurrence of `query` in `text`.
 * Returns ~120 chars of context with the match in the middle.
 */
function extractSnippet(text: string, query: string, contextLen = 60): string {
  const lower = text.toLowerCase();
  const qLower = query.toLowerCase();
  // Try to match each word individually if full query doesn't match
  let idx = lower.indexOf(qLower);
  if (idx === -1) {
    // Find first matching word
    const words = qLower.split(/\s+/).filter(Boolean);
    for (const w of words) {
      idx = lower.indexOf(w);
      if (idx !== -1) break;
    }
  }
  if (idx === -1) idx = 0;

  const start = Math.max(0, idx - contextLen);
  const end = Math.min(text.length, idx + query.length + contextLen);
  let snippet = text.slice(start, end).replace(/\n+/g, " ").trim();
  if (start > 0) snippet = "..." + snippet;
  if (end < text.length) snippet = snippet + "...";
  return snippet;
}

/** Full-text search, returns results grouped by thread */
export function search(query: string, limit = 100): GroupedSearchResult[] {
  if (!query.trim()) return [];

  const ids = flexIndex.search(query, limit) as number[];
  // Group by thread
  const groups = new Map<
    string,
    GroupedSearchResult
  >();

  for (const numKey of ids) {
    const msg = keyToMessage.get(numKey);
    if (!msg) continue;
    const thread = threadMap.get(msg.threadId);
    if (!thread) continue;

    let group = groups.get(msg.threadId);
    if (!group) {
      group = {
        threadId: thread.id,
        slug: thread.slug,
        title: thread.title,
        agent: thread.agent,
        model: thread.model,
        matches: [],
      };
      groups.set(msg.threadId, group);
    }
    group.matches.push({
      ordinal: msg.ordinal,
      role: msg.role,
      snippet: extractSnippet(msg.content, query),
    });
  }

  // Sort matches within each group by ordinal
  for (const group of groups.values()) {
    group.matches.sort((a, b) => a.ordinal - b.ordinal);
  }

  return Array.from(groups.values());
}

/** Get total number of indexed threads */
export function indexedCount(): number {
  return threadMap.size;
}

/**
 * IndexedDB wrapper for storing thread + message data locally.
 * Messages are stored individually for per-message search indexing.
 */

const DB_NAME = "replay-search";
const DB_VERSION = 2;
const THREADS_STORE = "threads";
const MESSAGES_STORE = "messages";
const META_STORE = "meta";

export interface StoredThread {
  id: string;
  slug: string;
  title: string | null;
  agent: string;
  model: string | null;
  visibility: string;
  tags: string[];
  messageCount: number;
  sessionTs: string;
  createdAt: string;
  updatedAt: string;
}

export interface StoredMessage {
  /** Composite key: `${threadId}:${ordinal}` */
  key: string;
  threadId: string;
  ordinal: number;
  role: string;
  content: string;
}

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      // Clean slate on version bump
      for (const name of Array.from(db.objectStoreNames)) {
        db.deleteObjectStore(name);
      }
      db.createObjectStore(THREADS_STORE, { keyPath: "id" });
      const msgStore = db.createObjectStore(MESSAGES_STORE, {
        keyPath: "key",
      });
      msgStore.createIndex("threadId", "threadId", { unique: false });
      db.createObjectStore(META_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

/** Upsert threads and their messages */
export async function putThreadsAndMessages(
  threads: StoredThread[],
  messages: StoredMessage[]
): Promise<void> {
  if (threads.length === 0) return;
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(
      [THREADS_STORE, MESSAGES_STORE],
      "readwrite"
    );
    const threadStore = tx.objectStore(THREADS_STORE);
    const msgStore = tx.objectStore(MESSAGES_STORE);

    for (const t of threads) {
      threadStore.put(t);
    }
    for (const m of messages) {
      msgStore.put(m);
    }

    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
  });
}

/** Get all stored threads */
export async function getAllThreads(): Promise<StoredThread[]> {
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(THREADS_STORE, "readonly");
    const req = tx.objectStore(THREADS_STORE).getAll();
    req.onsuccess = () => {
      db.close();
      resolve(req.result);
    };
    req.onerror = () => {
      db.close();
      reject(req.error);
    };
  });
}

/** Get all stored messages */
export async function getAllMessages(): Promise<StoredMessage[]> {
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(MESSAGES_STORE, "readonly");
    const req = tx.objectStore(MESSAGES_STORE).getAll();
    req.onsuccess = () => {
      db.close();
      resolve(req.result);
    };
    req.onerror = () => {
      db.close();
      reject(req.error);
    };
  });
}

/** Get the last sync timestamp */
export async function getSyncTs(): Promise<string | null> {
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(META_STORE, "readonly");
    const req = tx.objectStore(META_STORE).get("syncTs");
    req.onsuccess = () => {
      db.close();
      resolve(req.result ?? null);
    };
    req.onerror = () => {
      db.close();
      reject(req.error);
    };
  });
}

/** Set the last sync timestamp */
export async function setSyncTs(ts: string): Promise<void> {
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(META_STORE, "readwrite");
    tx.objectStore(META_STORE).put(ts, "syncTs");
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
  });
}

/** Clear everything (useful for logout / reset) */
export async function clearAll(): Promise<void> {
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(
      [THREADS_STORE, MESSAGES_STORE, META_STORE],
      "readwrite"
    );
    tx.objectStore(THREADS_STORE).clear();
    tx.objectStore(MESSAGES_STORE).clear();
    tx.objectStore(META_STORE).clear();
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
  });
}

import { type NextRequest, NextResponse, after } from "next/server";
import { gunzipSync } from "node:zlib";
import { nanoid } from "nanoid";
import { eq, and, desc, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { thread, message } from "@/lib/db/schema";
import { requireAuth, isCliRequest, checkCliVersion } from "@/lib/auth-helpers";
import {
  uploadThreadSchema,
  extractTextFromBlocks,
  type ContentBlock,
} from "@/lib/validations";
import { summarizeThread } from "@/lib/ai/summarize-thread";
import { buildConversationSnapshot } from "@/lib/thread-snapshot";
import { getPostHogClient } from "@/lib/posthog-server";

/**
 * POST /api/threads — Upload a thread from the CLI
 */
export async function POST(request: NextRequest) {
  if (!isCliRequest(request)) {
    return NextResponse.json(
      { error: "Threads can only be uploaded via the Replay CLI" },
      { status: 403 }
    );
  }

  const versionError = checkCliVersion(request);
  if (versionError) return versionError;

  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const compressed = Buffer.from(await request.arrayBuffer());
  const body: unknown = JSON.parse(gunzipSync(compressed).toString("utf-8"));
  const parsed = uploadThreadSchema.safeParse(body);

  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid request body", details: parsed.error.issues },
      { status: 400 }
    );
  }

  const { session: sessionData, messages } = parsed.data;

  // Check for duplicate upload
  const existing = await db
    .select({ slug: thread.slug })
    .from(thread)
    .where(
      and(
        eq(thread.ownerId, session.user.id),
        eq(thread.sessionId, sessionData.id)
      )
    )
    .limit(1);

  if (existing.length > 0) {
    return NextResponse.json(
      {
        error: "Session already uploaded",
        slug: existing[0].slug,
        url: `${process.env.NEXT_PUBLIC_APP_URL}/t/${existing[0].slug}`,
      },
      { status: 409 }
    );
  }

  const slug = nanoid(10);

  // Derive title: use session title, or extract from first user message
  let title = sessionData.title ?? null;
  if (!title) {
    const firstUserMsg = messages.find((m) => m.role === "user");
    if (firstUserMsg) {
      if ("content" in firstUserMsg && firstUserMsg.content) {
        title = extractTextFromBlocks(
          firstUserMsg.content as ContentBlock[]
        ).slice(0, 200);
      } else if ("text" in firstUserMsg && firstUserMsg.text) {
        title = firstUserMsg.text.slice(0, 200);
      }
    }
  }

  // Pre-process messages for insert and snapshot
  const processedMessages = messages.map((m, i) => {
    let contentText: string;
    let contentBlocks: ContentBlock[] | null = null;

    if ("content" in m && m.content && Array.isArray(m.content)) {
      contentBlocks = m.content as ContentBlock[];
      contentText = extractTextFromBlocks(contentBlocks);
    } else if ("text" in m && m.text) {
      contentText = m.text;
    } else {
      contentText = "";
    }

    return { ordinal: i, role: m.role, contentText, contentBlocks, timestamp: m.timestamp, raw: m };
  });

  const conversationSnapshot = buildConversationSnapshot(
    processedMessages.map((m) => ({
      role: m.role,
      content: m.contentText,
      contentBlocks: m.contentBlocks,
      redacted: false,
    }))
  );

  // Insert thread
  const [inserted] = await db
    .insert(thread)
    .values({
      ownerId: session.user.id,
      ownerType: "user",
      slug,
      visibility: "private",
      title: title || null,
      agent: sessionData.agent,
      model: sessionData.model ?? null,
      sessionId: sessionData.id,
      projectPath: sessionData.project_path ?? null,
      gitBranch: sessionData.git_branch ?? null,
      cliVersion: sessionData.cli_version ?? null,
      sessionTs: new Date(sessionData.timestamp),
      messageCount: messages.length,
      conversationSnapshot,
    })
    .returning({ id: thread.id, slug: thread.slug });

  // Insert messages
  if (processedMessages.length > 0) {
    await db.insert(message).values(
      processedMessages.map((m) => ({
        threadId: inserted.id,
        ordinal: m.ordinal,
        role: m.role,
        content: m.contentText,
        contentBlocks: m.contentBlocks ? JSON.stringify(m.contentBlocks) : null,
        messageModel: "model" in m.raw ? (m.raw.model ?? null) : null,
        stopReason: "stop_reason" in m.raw ? (m.raw.stop_reason ?? null) : null,
        usage: "usage" in m.raw && m.raw.usage ? JSON.stringify(m.raw.usage) : null,
        timestamp: new Date(m.timestamp),
      }))
    );
  }

  // Generate key points and verify/improve title in the background
  after(async () => {
    try {
      const textMessages = messages.map((m) => ({
        role: m.role,
        content:
          "content" in m && m.content
            ? extractTextFromBlocks(m.content as ContentBlock[])
            : "text" in m
              ? (m.text ?? "")
              : "",
      }));

      const { keyPoints, improvedTitle } = await summarizeThread(
        title,
        textMessages
      );

      const updates: Partial<typeof thread.$inferInsert> = {};
      if (keyPoints.length > 0) updates.keyPoints = keyPoints;
      if (improvedTitle) updates.title = improvedTitle;

      if (Object.keys(updates).length > 0) {
        await db
          .update(thread)
          .set(updates)
          .where(eq(thread.id, inserted.id));
      }
    } catch {
      // Silent failure — key points are non-critical
    }
  });

  const posthog = getPostHogClient();
  posthog.capture({
    distinctId: session.user.id,
    event: "thread_uploaded",
    properties: {
      thread_slug: inserted.slug,
      agent: sessionData.agent,
      model: sessionData.model ?? null,
      message_count: messages.length,
      cli_version: sessionData.cli_version ?? null,
    },
  });

  return NextResponse.json(
    {
      id: inserted.id,
      slug: inserted.slug,
      url: `${process.env.NEXT_PUBLIC_APP_URL}/t/${inserted.slug}`,
      visibility: "private" as const,
      message_count: messages.length,
    },
    { status: 201 }
  );
}

/**
 * GET /api/threads — List authenticated user's threads
 */
export async function GET(request: NextRequest) {
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const url = new URL(request.url);
  const page = Math.max(1, Number(url.searchParams.get("page") ?? "1"));
  const limit = Math.min(
    50,
    Math.max(1, Number(url.searchParams.get("limit") ?? "20"))
  );
  const visibility = url.searchParams.get("visibility");
  const offset = (page - 1) * limit;

  const conditions = [eq(thread.ownerId, session.user.id)];
  if (
    visibility &&
    ["private", "shared", "unlisted", "public"].includes(visibility)
  ) {
    conditions.push(eq(thread.visibility, visibility));
  }

  const where = and(...conditions);

  const [threads, countResult] = await Promise.all([
    db
      .select({
        id: thread.id,
        slug: thread.slug,
        title: thread.title,
        agent: thread.agent,
        model: thread.model,
        visibility: thread.visibility,
        keyPoints: thread.keyPoints,

        messageCount: thread.messageCount,
        sessionTs: thread.sessionTs,
        createdAt: thread.createdAt,
      })
      .from(thread)
      .where(where)
      .orderBy(desc(thread.createdAt))
      .limit(limit)
      .offset(offset),
    db
      .select({ count: sql<number>`count(*)::int` })
      .from(thread)
      .where(where),
  ]);

  return NextResponse.json({
    threads,
    total: countResult[0].count,
    page,
    limit,
  });
}

import Anthropic from "@anthropic-ai/sdk";
import { requireAuth } from "@/lib/auth-helpers";
import { THREAD_TOOLS, executeServerTool } from "@/lib/ai/tools";
import { getPostHogClient } from "@/lib/posthog-server";

const client = new Anthropic({
  apiKey: process.env.ANTHROPIC_API_KEY!,
});

const TOOLS = THREAD_TOOLS;

/** Tools that the client resolves via FlexSearch */
const CLIENT_TOOLS = new Set(["search_threads"]);

// ---------------------------------------------------------------------------
// SSE helpers
// ---------------------------------------------------------------------------

type SSEEvent =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown>; locality: "client" | "server" }
  | { type: "tool_result"; name: string }
  | { type: "pause"; assistantContent: Anthropic.Messages.ContentBlock[]; serverToolResults?: Anthropic.Messages.ToolResultBlockParam[] }
  | { type: "error"; message: string };

function encodeSSE(event: SSEEvent | "[DONE]"): Uint8Array {
  const encoder = new TextEncoder();
  if (event === "[DONE]") {
    return encoder.encode("data: [DONE]\n\n");
  }
  return encoder.encode(`data: ${JSON.stringify(event)}\n\n`);
}

// ---------------------------------------------------------------------------
// Route handler
// ---------------------------------------------------------------------------

export async function POST(request: Request) {
  const [session, errorResponse] = await requireAuth(request);
  if (errorResponse) return errorResponse;

  const body = await request.json();
  const { messages: inputMessages, activeThread, continuation } = body as {
    messages: { role: "user" | "assistant"; content: string }[];
    activeThread?: string | null;
    continuation?: {
      assistantContent: Anthropic.Messages.ContentBlock[];
      toolResults: {
        type: "tool_result";
        tool_use_id: string;
        content: string;
      }[];
    };
  };

  if (!inputMessages || inputMessages.length === 0) {
    return new Response(JSON.stringify({ error: "Messages required" }), {
      status: 400,
    });
  }

  if (!continuation) {
    const posthog = getPostHogClient();
    posthog.capture({
      distinctId: session.user.id,
      event: "assistant_queried",
      properties: {
        has_active_thread: !!activeThread,
      },
    });
  }

  // Build the conversation messages for the API
  const apiMessages: Anthropic.Messages.MessageParam[] = inputMessages.map(
    (m) => ({ role: m.role, content: m.content })
  );

  // If this is a continuation after client-side tool resolution,
  // append the assistant's tool_use response and the tool results
  if (continuation) {
    apiMessages.push({
      role: "assistant",
      content: continuation.assistantContent,
    });
    apiMessages.push({
      role: "user",
      content: continuation.toolResults.map((tr) => ({
        type: "tool_result" as const,
        tool_use_id: tr.tool_use_id,
        content: tr.content,
      })) as Anthropic.Messages.ToolResultBlockParam[],
    });
  }

  const systemParts = [
    "You are a helpful assistant for replay.md, a platform that stores and shares AI coding conversation sessions.",
    "Be concise and direct. Use markdown formatting. Never use emojis.",
    "Answer what the user asks. Do not suggest next steps, offer unsolicited help, or ask what they'd like to do. Just answer their question and stop.",
    "You have tools to search, list, and read the user's conversations. Use them when you need information — don't guess or hallucinate conversation content.",
    "When referencing conversations, always use markdown links with the thread title as display text: [Title](/t/slug).",
    "To reference specific messages, append the message hash: [Title #m5](/t/slug#m5). For message ranges: [Title #m3-m7](/t/slug#m3-m7).",
    "Always use the full /t/slug path in links, even for the thread the user is currently viewing. Never use hash-only links like (#m5).",
    "Never output raw slugs — always wrap in a markdown link.",
  ];

  if (activeThread) {
    systemParts.push(
      "The user is currently viewing a specific conversation. They opened the assistant from within that conversation.",
      "Prioritize answering questions about this active conversation.",
      "When the user asks questions without specifying which conversation, assume they mean the one they're currently viewing."
    );
  } else {
    systemParts.push(
      "The user is on the dashboard or profile page viewing their conversations.",
      "Help them find, understand, and navigate their stored conversations.",
      "Use the search and list tools to find relevant conversations rather than relying on memory."
    );
  }

  const systemPrompt = systemParts.join("\n");
  const userId = session.user.id;
  const traceId = crypto.randomUUID();

  const readable = new ReadableStream({
    async start(controller) {
      try {
        await runAgentLoop(controller, systemPrompt, apiMessages, userId, traceId);
        controller.enqueue(encodeSSE("[DONE]"));
        controller.close();
      } catch (err) {
        const message =
          err instanceof Anthropic.APIError
            ? `API error: ${err.status} ${err.message}`
            : "Stream failed";
        controller.enqueue(encodeSSE({ type: "error", message }));
        controller.enqueue(encodeSSE("[DONE]"));
        controller.close();
      }
    },
  });

  return new Response(readable, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    },
  });
}

// ---------------------------------------------------------------------------
// Agent loop — streams text, resolves server tools, pauses for client tools
// ---------------------------------------------------------------------------

async function runAgentLoop(
  controller: ReadableStreamDefaultController,
  systemPrompt: string,
  messages: Anthropic.Messages.MessageParam[],
  userId: string,
  traceId: string,
  maxIterations = 10
): Promise<void> {
  for (let i = 0; i < maxIterations; i++) {
    const stream = client.messages.stream({
      model: "claude-haiku-4-5",
      max_tokens: 4096,
      system: systemPrompt,
      tools: TOOLS,
      messages,
    });

    // Track tool_use blocks as they appear inline during streaming.
    // content_block_start gives us the id + name, input_json_delta
    // accumulates the input JSON, content_block_stop means it's complete.
    let pendingToolBlock: {
      id: string;
      name: string;
      inputJson: string;
    } | null = null;

    for await (const event of stream) {
      // Stream text deltas immediately
      if (
        event.type === "content_block_delta" &&
        event.delta.type === "text_delta"
      ) {
        controller.enqueue(
          encodeSSE({ type: "text", text: event.delta.text })
        );
      }

      // Detect tool_use block starting — send the sprite event inline
      if (
        event.type === "content_block_start" &&
        event.content_block.type === "tool_use"
      ) {
        pendingToolBlock = {
          id: event.content_block.id,
          name: event.content_block.name,
          inputJson: "",
        };
      }

      // Accumulate tool input JSON deltas
      if (
        event.type === "content_block_delta" &&
        event.delta.type === "input_json_delta" &&
        pendingToolBlock
      ) {
        pendingToolBlock.inputJson += event.delta.partial_json;
      }

      // Tool block complete — emit inline tool_use event
      if (event.type === "content_block_stop" && pendingToolBlock) {
        let input: Record<string, unknown> = {};
        try {
          input = JSON.parse(pendingToolBlock.inputJson || "{}");
        } catch {}

        const isClient = CLIENT_TOOLS.has(pendingToolBlock.name);
        controller.enqueue(
          encodeSSE({
            type: "tool_use",
            id: pendingToolBlock.id,
            name: pendingToolBlock.name,
            input,
            locality: isClient ? "client" : "server",
          })
        );
        pendingToolBlock = null;
      }
    }

    // Get the final message to check stop reason and collect tool blocks
    const finalMessage = await stream.finalMessage();

    if (finalMessage.stop_reason !== "tool_use") {
      return;
    }

    const toolUseBlocks = finalMessage.content.filter(
      (b): b is Anthropic.Messages.ToolUseBlock => b.type === "tool_use"
    );

    // Add the assistant response to the conversation
    messages.push({ role: "assistant", content: finalMessage.content });

    // Separate client and server tools
    const clientTools: Anthropic.Messages.ToolUseBlock[] = [];
    const serverTools: Anthropic.Messages.ToolUseBlock[] = [];
    for (const toolUse of toolUseBlocks) {
      if (CLIENT_TOOLS.has(toolUse.name)) {
        clientTools.push(toolUse);
      } else {
        serverTools.push(toolUse);
      }
    }

    // Resolve all server-side tools
    const toolResultBlocks: Anthropic.Messages.ToolResultBlockParam[] = [];
    for (const toolUse of serverTools) {
      const result = await executeServerTool(
        toolUse.name,
        toolUse.input as Record<string, unknown>,
        userId
      );
      toolResultBlocks.push({
        type: "tool_result",
        tool_use_id: toolUse.id,
        content: result,
      });
      controller.enqueue(
        encodeSSE({ type: "tool_result", name: toolUse.name })
      );
    }

    if (clientTools.length > 0) {
      // Pause for client-side tools
      controller.enqueue(
        encodeSSE({
          type: "pause",
          assistantContent: finalMessage.content,
          serverToolResults: toolResultBlocks.length > 0 ? toolResultBlocks : undefined,
        })
      );
      return;
    }

    // All tools were server-side — add results and continue the loop
    messages.push({ role: "user", content: toolResultBlocks });
  }
}

import { NextResponse, after } from "next/server";
import { nanoid } from "nanoid";
import { eq, desc } from "drizzle-orm";
import { db } from "@/lib/db";
import { decisionTrace } from "@/lib/db/schema";
import { requireAuth } from "@/lib/auth-helpers";
import { getGlobalConfig, type DecisionTracesConfig } from "@/lib/config";
import { generateTrace } from "@/lib/ai/generate-trace";
import { getPostHogClient } from "@/lib/posthog-server";

export async function GET(request: Request) {
  const cfg = await getGlobalConfig<DecisionTracesConfig>("decision_traces");
  if (!cfg.enabled) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const [session, errorResponse] = await requireAuth(request);
  if (errorResponse) return errorResponse;

  const traces = await db
    .select({
      id: decisionTrace.id,
      slug: decisionTrace.slug,
      question: decisionTrace.question,
      projectPath: decisionTrace.projectPath,
      status: decisionTrace.status,
      createdAt: decisionTrace.createdAt,
      updatedAt: decisionTrace.updatedAt,
    })
    .from(decisionTrace)
    .where(eq(decisionTrace.ownerId, session.user.id))
    .orderBy(desc(decisionTrace.createdAt));

  return NextResponse.json({ traces });
}

export async function POST(request: Request) {
  const cfg = await getGlobalConfig<DecisionTracesConfig>("decision_traces");
  if (!cfg.enabled) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const [session, errorResponse] = await requireAuth(request);
  if (errorResponse) return errorResponse;

  const body = await request.json();
  const { question, projectPath } = body as {
    question?: string;
    projectPath?: string;
  };

  if (!question || question.trim().length === 0) {
    return NextResponse.json(
      { error: "Question is required" },
      { status: 400 }
    );
  }

  if (question.length > 500) {
    return NextResponse.json(
      { error: "Question must be 500 characters or less" },
      { status: 400 }
    );
  }

  const slug = nanoid(10);
  const userId = session.user.id;

  const [inserted] = await db
    .insert(decisionTrace)
    .values({
      ownerId: userId,
      slug,
      question: question.trim(),
      projectPath: projectPath || null,
      status: "generating",
    })
    .returning({ id: decisionTrace.id, slug: decisionTrace.slug });

  getPostHogClient().capture({
    distinctId: userId,
    event: "trace_created",
    properties: {
      trace_slug: inserted.slug,
      question: question.trim(),
      has_project_scope: !!projectPath,
    },
  });

  // Fire-and-forget background generation
  after(async () => {
    await generateTrace(inserted.id, inserted.slug, userId, question.trim(), projectPath);
  });

  return NextResponse.json(
    { id: inserted.id, slug: inserted.slug },
    { status: 201 }
  );
}

import { type NextRequest, NextResponse } from "next/server";
import { sql } from "drizzle-orm";
import { requireAuth } from "@/lib/auth-helpers";
import { usernameSchema } from "@/lib/validations";
import { db } from "@/lib/db";

/**
 * GET /api/username/available?username=foo — Check username availability
 */
export async function GET(request: NextRequest) {
  const [, authError] = await requireAuth(request);
  if (authError) return authError;

  const url = new URL(request.url);
  const username = url.searchParams.get("username");

  if (!username) {
    return NextResponse.json(
      { error: "Username query parameter is required" },
      { status: 400 }
    );
  }

  const parsed = usernameSchema.safeParse(username);
  if (!parsed.success) {
    return NextResponse.json({ available: false, reason: "invalid" });
  }

  const existing = await db.execute<{ id: string }>(
    sql`SELECT id FROM "user" WHERE LOWER(username) = ${parsed.data.toLowerCase()} LIMIT 1`
  );

  return NextResponse.json({
    available: !existing.rows || existing.rows.length === 0,
  });
}

import { type NextRequest, NextResponse } from "next/server";
import { eq, and, desc, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { thread } from "@/lib/db/schema";

/**
 * GET /api/users/[username] — Public profile with public threads
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ username: string }> }
) {
  const { username } = await params;

  // Find user by username
  const users = await db.execute<{
    id: string;
    name: string;
    username: string;
    image: string | null;
  }>(sql`SELECT id, name, username, image FROM "user" WHERE LOWER(username) = ${username.toLowerCase()} LIMIT 1`);

  const user = users.rows?.[0];

  if (!user) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  // Get their public threads
  const threads = await db
    .select({
      id: thread.id,
      slug: thread.slug,
      title: thread.title,
      agent: thread.agent,
      model: thread.model,
      messageCount: thread.messageCount,
      sessionTs: thread.sessionTs,
      createdAt: thread.createdAt,
    })
    .from(thread)
    .where(
      and(eq(thread.ownerId, user.id), eq(thread.visibility, "public"))
    )
    .orderBy(desc(thread.createdAt))
    .limit(50);

  return NextResponse.json({
    user: {
      name: user.name,
      username: user.username,
      image: user.image,
    },
    threads,
  });
}

import { eq, asc, and, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { thread, message, threadShare } from "@/lib/db/schema";
import { auth } from "@/lib/auth";
import { headers } from "next/headers";
import { buildPipeline, processDeep } from "@/lib/thread-processors";

// --- Content block types (mirrors content-renderer.tsx) ---

interface TextBlock {
  type: "text";
  text: string;
}

interface ThinkingBlock {
  type: "thinking";
  thinking: string;
}

interface ToolUseBlock {
  type: "tool_use";
  id: string;
  name: string;
  input: Record<string, unknown>;
}

interface ToolResultBlock {
  type: "tool_result";
  tool_use_id: string;
  content:
    | string
    | Array<{ type: string; text?: string }>;
  is_error?: boolean;
}

type ContentBlock = TextBlock | ThinkingBlock | ToolUseBlock | ToolResultBlock;

// --- Markdown rendering ---

function renderContentBlocks(blocks: ContentBlock[]): string {
  const parts: string[] = [];

  for (const block of blocks) {
    switch (block.type) {
      case "text":
        if (block.text.trim()) parts.push(block.text);
        break;

      case "thinking":
        if (block.thinking.trim()) {
          parts.push(
            `<details>\n<summary>Thinking</summary>\n\n${block.thinking}\n\n</details>`
          );
        }
        break;

      case "tool_use": {
        const inputStr = JSON.stringify(block.input, null, 2);
        parts.push(
          `> **${block.name}**\n> \`\`\`json\n${inputStr
            .split("\n")
            .map((l) => `> ${l}`)
            .join("\n")}\n> \`\`\``
        );
        break;
      }

      case "tool_result": {
        const resultText =
          typeof block.content === "string"
            ? block.content
            : block.content
                .filter((c) => c.text)
                .map((c) => c.text)
                .join("\n");
        if (resultText.trim()) {
          const label = block.is_error ? "Tool Error" : "Tool Result";
          parts.push(`> **${label}**:\n> ${resultText.split("\n").map((l) => `> ${l}`).join("\n")}`);
        }
        break;
      }
    }
  }

  return parts.join("\n\n");
}

function renderMessage(
  content: string,
  contentBlocks: ContentBlock[] | null,
  redacted: boolean
): string {
  if (redacted) return `*[redacted]*`;

  // If structured content blocks exist, use them
  if (contentBlocks && contentBlocks.length > 0) {
    const rendered = renderContentBlocks(contentBlocks);
    if (rendered.trim()) return rendered;
  }

  // Fall back to plain content
  return content;
}

function formatDate(iso: string): string {
  return new Date(iso).toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
}

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;

  // Fetch thread
  const threads = await db
    .select()
    .from(thread)
    .where(eq(thread.slug, slug))
    .limit(1);

  const threadRow = threads[0];
  if (!threadRow) {
    return new Response("Not found", { status: 404 });
  }

  // Access control (same as page.tsx)
  const headersList = await headers();
  const session = await auth.api.getSession({ headers: headersList });
  const userId = session?.user.id ?? null;
  const isOwner = userId === threadRow.ownerId;

  if (threadRow.visibility === "private" && !isOwner) {
    return new Response("Not found", { status: 404 });
  }
  if (threadRow.visibility === "shared" && !isOwner) {
    if (!userId) return new Response("Not found", { status: 404 });
    const shares = await db
      .select({ id: threadShare.id })
      .from(threadShare)
      .where(
        and(
          eq(threadShare.threadId, threadRow.id),
          eq(threadShare.userId, userId)
        )
      )
      .limit(1);
    if (shares.length === 0) {
      return new Response("Not found", { status: 404 });
    }
  }

  // Fetch messages
  const messages = await db
    .select()
    .from(message)
    .where(eq(message.threadId, threadRow.id))
    .orderBy(asc(message.ordinal));

  // Fetch owner
  const ownerRows = await db.execute<{ name: string; username: string | null }>(
    sql`SELECT name, username FROM "user" WHERE id = ${threadRow.ownerId} LIMIT 1`
  );
  const owner = ownerRows.rows?.[0] ?? { name: "Unknown", username: null };

  // Process content (path relativization)
  const processor = buildPipeline({ projectPath: threadRow.projectPath });

  const agentLabel =
    threadRow.agent === "claude"
      ? "Claude Code"
      : threadRow.agent === "codex"
        ? "Codex"
        : threadRow.agent;

  const promptCount = messages.filter((m) => m.role === "user").length;

  // Build markdown
  const lines: string[] = [];

  // Header
  lines.push(`# ${threadRow.title ?? "Untitled conversation"}`);
  lines.push("");
  lines.push(
    `> ${owner.name} · ${agentLabel}${threadRow.model ? ` · ${threadRow.model}` : ""} · ${formatDate(threadRow.sessionTs.toISOString())}`
  );
  lines.push(
    `> ${promptCount} prompts · ${threadRow.messageCount} messages`
  );

  if (threadRow.tags && threadRow.tags.length > 0) {
    lines.push(`> Tags: ${threadRow.tags.join(", ")}`);
  }

  lines.push("");
  lines.push("---");
  lines.push("");

  // Messages
  for (const m of messages) {
    const heading = m.role === "user" ? "## Human" : "## Assistant";
    lines.push(heading);
    lines.push("");

    const isRedacted = m.redacted && !isOwner;
    const content = isRedacted ? "" : m.content;
    const contentBlocks: ContentBlock[] | null = isRedacted
      ? null
      : (m.contentBlocks as ContentBlock[] | null) ?? null;

    // Apply path processing
    const processed = processor
      ? processDeep({ content, contentBlocks }, processor)
      : { content, contentBlocks };

    const rendered = renderMessage(
      processed.content,
      processed.contentBlocks,
      isRedacted
    );

    lines.push(rendered);
    lines.push("");
  }

  const markdown = lines.join("\n");

  return new Response(markdown, {
    headers: {
      "Content-Type": "text/markdown; charset=utf-8",
      "Vary": "Accept",
      "Content-Disposition": `inline; filename="${slug}.md"`,
    },
  });
}

import { type NextRequest, NextResponse, after } from "next/server";
import { gunzipSync } from "node:zlib";
import { eq, and, asc } from "drizzle-orm";
import { db } from "@/lib/db";
import { thread, message, threadShare } from "@/lib/db/schema";
import { requireAuth, getOptionalSession, isCliRequest, checkCliVersion } from "@/lib/auth-helpers";
import {
  updateThreadSchema,
  uploadThreadSchema,
  extractTextFromBlocks,
  type ContentBlock,
} from "@/lib/validations";
import { summarizeThread } from "@/lib/ai/summarize-thread";
import { buildConversationSnapshot } from "@/lib/thread-snapshot";
import { getPostHogClient } from "@/lib/posthog-server";

async function findThread(slug: string) {
  const rows = await db
    .select()
    .from(thread)
    .where(eq(thread.slug, slug))
    .limit(1);
  return rows[0] ?? null;
}

async function canView(
  threadRow: typeof thread.$inferSelect,
  userId: string | null
): Promise<boolean> {
  if (
    threadRow.visibility === "public" ||
    threadRow.visibility === "unlisted"
  ) {
    return true;
  }
  if (!userId) return false;
  if (threadRow.ownerId === userId) return true;
  if (threadRow.visibility === "shared") {
    const share = await db
      .select({ id: threadShare.id })
      .from(threadShare)
      .where(
        and(
          eq(threadShare.threadId, threadRow.id),
          eq(threadShare.userId, userId)
        )
      )
      .limit(1);
    return share.length > 0;
  }
  return false;
}

/**
 * GET /api/threads/[slug] — Get a thread with messages
 */
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  const threadRow = await findThread(slug);

  if (!threadRow) {
    return NextResponse.json({ error: "Thread not found" }, { status: 404 });
  }

  const session = await getOptionalSession(request);
  const userId = session?.user.id ?? null;

  if (!(await canView(threadRow, userId))) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const isOwner = userId === threadRow.ownerId;

  const messages = await db
    .select()
    .from(message)
    .where(eq(message.threadId, threadRow.id))
    .orderBy(asc(message.ordinal));

  return NextResponse.json({
    thread: {
      id: threadRow.id,
      slug: threadRow.slug,
      title: threadRow.title,
      agent: threadRow.agent,
      model: threadRow.model,
      visibility: threadRow.visibility,
      projectPath: threadRow.projectPath,
      gitBranch: threadRow.gitBranch,
      cliVersion: threadRow.cliVersion,
      keyPoints: threadRow.keyPoints,

      messageCount: threadRow.messageCount,
      sessionTs: threadRow.sessionTs,
      createdAt: threadRow.createdAt,
    },
    messages: messages.map((m) => ({
      id: m.id,
      ordinal: m.ordinal,
      role: m.role,
      content: m.redacted && !isOwner ? "" : m.content,
      contentBlocks:
        m.redacted && !isOwner ? null : (m.contentBlocks ?? null),
      model: m.messageModel,
      stopReason: m.stopReason,
      usage: m.usage,
      redacted: m.redacted,
      timestamp: m.timestamp,
    })),
  });
}

/**
 * PATCH /api/threads/[slug] — Update thread (owner only)
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const threadRow = await findThread(slug);

  if (!threadRow || threadRow.ownerId !== session.user.id) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const body: unknown = await request.json();
  const parsed = updateThreadSchema.safeParse(body);

  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid request body", details: parsed.error.issues },
      { status: 400 }
    );
  }

  const { visibility, title, tags, redactions } = parsed.data;

  const updates: Partial<typeof thread.$inferInsert> = {
    updatedAt: new Date(),
  };
  if (visibility !== undefined) updates.visibility = visibility;
  if (title !== undefined) updates.title = title;
  if (tags !== undefined) updates.tags = tags;

  await db.update(thread).set(updates).where(eq(thread.id, threadRow.id));

  if (redactions && redactions.length > 0) {
    for (const r of redactions) {
      await db
        .update(message)
        .set({ redacted: r.redacted })
        .where(
          and(eq(message.id, r.message_id), eq(message.threadId, threadRow.id))
        );
    }

    // Recompute snapshot since redaction affects it
    const msgs = await db
      .select({
        role: message.role,
        content: message.content,
        contentBlocks: message.contentBlocks,
        redacted: message.redacted,
      })
      .from(message)
      .where(eq(message.threadId, threadRow.id))
      .orderBy(asc(message.ordinal));

    const snapshot = buildConversationSnapshot(msgs);
    await db
      .update(thread)
      .set({ conversationSnapshot: snapshot })
      .where(eq(thread.id, threadRow.id));
  }

  return NextResponse.json({ updated: true });
}

/**
 * PUT /api/threads/[slug] — Re-upload a session from the CLI (owner only)
 *
 * Accepts the same payload as POST /api/threads. Replaces all messages
 * and updates metadata. Bumps updatedAt. Preserves slug, visibility, tags,
 * and shares.
 */
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  if (!isCliRequest(request)) {
    return NextResponse.json(
      { error: "Re-upload is only available via the Replay CLI" },
      { status: 403 }
    );
  }

  const versionError = checkCliVersion(request);
  if (versionError) return versionError;

  const { slug } = await params;
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const threadRow = await findThread(slug);

  if (!threadRow || threadRow.ownerId !== session.user.id) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const compressed = Buffer.from(await request.arrayBuffer());
  const body: unknown = JSON.parse(gunzipSync(compressed).toString("utf-8"));
  const parsed = uploadThreadSchema.safeParse(body);

  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid request body", details: parsed.error.issues },
      { status: 400 }
    );
  }

  const { session: sessionData, messages: msgs } = parsed.data;

  // Derive title
  let title = sessionData.title ?? null;
  if (!title) {
    const firstUserMsg = msgs.find((m) => m.role === "user");
    if (firstUserMsg) {
      if ("content" in firstUserMsg && firstUserMsg.content) {
        title = extractTextFromBlocks(
          firstUserMsg.content as ContentBlock[]
        ).slice(0, 200);
      } else if ("text" in firstUserMsg && firstUserMsg.text) {
        title = firstUserMsg.text.slice(0, 200);
      }
    }
  }

  // Pre-process messages for insert and snapshot
  const processedMessages = msgs.map((m, i) => {
    let contentText: string;
    let contentBlocks: ContentBlock[] | null = null;

    if ("content" in m && m.content && Array.isArray(m.content)) {
      contentBlocks = m.content as ContentBlock[];
      contentText = extractTextFromBlocks(contentBlocks);
    } else if ("text" in m && m.text) {
      contentText = m.text;
    } else {
      contentText = "";
    }

    return { ordinal: i, role: m.role, contentText, contentBlocks, timestamp: m.timestamp, raw: m };
  });

  const conversationSnapshot = buildConversationSnapshot(
    processedMessages.map((m) => ({
      role: m.role,
      content: m.contentText,
      contentBlocks: m.contentBlocks,
      redacted: false,
    }))
  );

  // Update thread metadata (preserve visibility, tags, shares)
  await db
    .update(thread)
    .set({
      title: title || null,
      agent: sessionData.agent,
      model: sessionData.model ?? null,
      projectPath: sessionData.project_path ?? null,
      gitBranch: sessionData.git_branch ?? null,
      cliVersion: sessionData.cli_version ?? null,
      sessionTs: new Date(sessionData.timestamp),
      messageCount: msgs.length,
      conversationSnapshot,
      updatedAt: new Date(),
    })
    .where(eq(thread.id, threadRow.id));

  // Replace messages: delete old, insert new
  await db.delete(message).where(eq(message.threadId, threadRow.id));

  if (processedMessages.length > 0) {
    await db.insert(message).values(
      processedMessages.map((m) => ({
        threadId: threadRow.id,
        ordinal: m.ordinal,
        role: m.role,
        content: m.contentText,
        contentBlocks: m.contentBlocks ? JSON.stringify(m.contentBlocks) : null,
        messageModel: "model" in m.raw ? (m.raw.model ?? null) : null,
        stopReason: "stop_reason" in m.raw ? (m.raw.stop_reason ?? null) : null,
        usage: "usage" in m.raw && m.raw.usage ? JSON.stringify(m.raw.usage) : null,
        timestamp: new Date(m.timestamp),
      }))
    );
  }

  // Regenerate key points and verify/improve title in the background
  after(async () => {
    try {
      const textMessages = msgs.map((m) => ({
        role: m.role,
        content:
          "content" in m && m.content
            ? extractTextFromBlocks(m.content as ContentBlock[])
            : "text" in m
              ? (m.text ?? "")
              : "",
      }));

      const { keyPoints, improvedTitle } = await summarizeThread(
        title,
        textMessages
      );

      const updates: Partial<typeof thread.$inferInsert> = {
        keyPoints: keyPoints.length > 0 ? keyPoints : null,
      };
      if (improvedTitle) updates.title = improvedTitle;

      await db
        .update(thread)
        .set(updates)
        .where(eq(thread.id, threadRow.id));
    } catch {
      // Silent failure — key points are non-critical
    }
  });

  const posthog = getPostHogClient();
  posthog.capture({
    distinctId: session.user.id,
    event: "thread_reuploaded",
    properties: {
      thread_slug: threadRow.slug,
      agent: sessionData.agent,
      model: sessionData.model ?? null,
      message_count: msgs.length,
      cli_version: sessionData.cli_version ?? null,
    },
  });

  return NextResponse.json({
    id: threadRow.id,
    slug: threadRow.slug,
    url: `${process.env.NEXT_PUBLIC_APP_URL}/t/${threadRow.slug}`,
    message_count: msgs.length,
    updated: true,
  });
}

/**
 * DELETE /api/threads/[slug] — Delete thread (owner only)
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const threadRow = await findThread(slug);

  if (!threadRow || threadRow.ownerId !== session.user.id) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  await db.delete(thread).where(eq(thread.id, threadRow.id));

  const posthog = getPostHogClient();
  posthog.capture({
    distinctId: session.user.id,
    event: "thread_deleted",
    properties: {
      thread_slug: slug,
    },
  });

  return new NextResponse(null, { status: 204 });
}

import { type NextRequest, NextResponse } from "next/server";
import { eq, and, gt, desc, asc, inArray } from "drizzle-orm";
import { db } from "@/lib/db";
import { thread, message } from "@/lib/db/schema";
import { requireAuth } from "@/lib/auth-helpers";

/**
 * Build searchable text from a message's content + contentBlocks.
 * Includes text blocks, tool_use inputs, and tool_result content (truncated).
 */
function buildSearchableContent(
  plainContent: string,
  contentBlocks: unknown
): string {
  if (!contentBlocks || !Array.isArray(contentBlocks)) {
    return plainContent;
  }

  const parts: string[] = [];

  for (const block of contentBlocks) {
    const b = block as Record<string, unknown>;
    if (b.type === "text" && typeof b.text === "string") {
      parts.push(b.text);
    } else if (b.type === "tool_use" && b.input && typeof b.input === "object") {
      // Index tool input values (file paths, commands, etc.)
      const values = Object.values(b.input as Record<string, unknown>);
      for (const v of values) {
        if (typeof v === "string") {
          parts.push(v);
        }
      }
    } else if (b.type === "tool_result") {
      // Truncate tool results to keep index size reasonable
      if (typeof b.content === "string") {
        parts.push(b.content.slice(0, 500));
      } else if (Array.isArray(b.content)) {
        for (const item of b.content as Array<Record<string, unknown>>) {
          if (item.type === "text" && typeof item.text === "string") {
            parts.push((item.text as string).slice(0, 500));
          }
        }
      }
    }
  }

  return parts.join("\n");
}

/**
 * GET /api/threads/sync?since=<ISO timestamp>
 *
 * Returns threads updated after `since` with their individual messages
 * for client-side per-message search indexing.
 * If `since` is omitted, returns all threads.
 *
 * Response shape:
 *   { threads: SyncThread[], syncTs: string }
 *
 * Each SyncThread includes a `messages` array with { ordinal, role, content }.
 */
export async function GET(request: NextRequest) {
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const url = new URL(request.url);
  const since = url.searchParams.get("since");

  const conditions = [eq(thread.ownerId, session.user.id)];
  if (since) {
    const sinceDate = new Date(since);
    if (isNaN(sinceDate.getTime())) {
      return NextResponse.json(
        { error: "Invalid `since` timestamp" },
        { status: 400 }
      );
    }
    conditions.push(gt(thread.updatedAt, sinceDate));
  }

  const where = and(...conditions);

  // Capture server time before query so the client can use it as next `since`
  const syncTs = new Date().toISOString();

  // Fetch thread metadata
  const threads = await db
    .select({
      id: thread.id,
      slug: thread.slug,
      title: thread.title,
      agent: thread.agent,
      model: thread.model,
      visibility: thread.visibility,
      tags: thread.tags,
      keyPoints: thread.keyPoints,

      messageCount: thread.messageCount,
      sessionTs: thread.sessionTs,
      createdAt: thread.createdAt,
      updatedAt: thread.updatedAt,
    })
    .from(thread)
    .where(where)
    .orderBy(desc(thread.updatedAt));

  if (threads.length === 0) {
    return NextResponse.json({ threads: [], syncTs });
  }

  // Fetch all messages for these threads in one query
  const threadIds = threads.map((t) => t.id);
  const messages = await db
    .select({
      threadId: message.threadId,
      ordinal: message.ordinal,
      role: message.role,
      content: message.content,
      contentBlocks: message.contentBlocks,
    })
    .from(message)
    .where(inArray(message.threadId, threadIds))
    .orderBy(asc(message.ordinal));

  // Group messages by thread
  const messagesByThread = new Map<string, typeof messages>();
  for (const m of messages) {
    let arr = messagesByThread.get(m.threadId);
    if (!arr) {
      arr = [];
      messagesByThread.set(m.threadId, arr);
    }
    arr.push(m);
  }

  const result = threads.map((t) => ({
    ...t,
    messages: (messagesByThread.get(t.id) ?? []).map((m) => ({
      ordinal: m.ordinal,
      role: m.role,
      content: buildSearchableContent(m.content, m.contentBlocks),
    })),
  }));

  return NextResponse.json({ threads: result, syncTs });
}

import { type NextRequest, NextResponse } from "next/server";
import { sql } from "drizzle-orm";
import { requireAuth } from "@/lib/auth-helpers";
import { auth } from "@/lib/auth";
import { usernameSchema } from "@/lib/validations";
import { db } from "@/lib/db";
import { getPostHogClient } from "@/lib/posthog-server";

/**
 * GET /api/users/me — Get current user profile
 */
export async function GET(request: NextRequest) {
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  return NextResponse.json({
    user: {
      id: session.user.id,
      name: session.user.name,
      email: session.user.email,
      image: session.user.image,
      username: (session.user as Record<string, unknown>).username ?? null,
    },
  });
}

/**
 * PATCH /api/users/me — Update username
 */
export async function PATCH(request: NextRequest) {
  const [session, authError] = await requireAuth(request);
  if (authError) return authError;

  const body = (await request.json()) as { username?: string };

  if (!body.username) {
    return NextResponse.json(
      { error: "Username is required" },
      { status: 400 }
    );
  }

  const parsed = usernameSchema.safeParse(body.username);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid username", details: parsed.error.issues },
      { status: 400 }
    );
  }

  const username = parsed.data.toLowerCase();

  const existing = await db.execute<{ id: string }>(
    sql`SELECT id FROM "user" WHERE LOWER(username) = ${username} AND id != ${session.user.id} LIMIT 1`
  );

  if (existing.rows && existing.rows.length > 0) {
    return NextResponse.json(
      { error: "Username already taken" },
      { status: 409 }
    );
  }

  const previousUsername = (session.user as Record<string, unknown>).username as string | null;

  await auth.api.updateUser({
    headers: request.headers,
    body: { username },
  });

  const posthog = getPostHogClient();
  posthog.capture({
    distinctId: session.user.id,
    event: "username_claimed",
    properties: {
      username,
      is_first_time: !previousUsername,
    },
  });
  posthog.identify({
    distinctId: session.user.id,
    properties: { username },
  });

  return NextResponse.json({ username });
}

import { NextResponse } from "next/server";
import { eq, and } from "drizzle-orm";
import { db } from "@/lib/db";
import { decisionTrace } from "@/lib/db/schema";
import { requireAuth } from "@/lib/auth-helpers";
import { getGlobalConfig, type DecisionTracesConfig } from "@/lib/config";
import { getPostHogClient } from "@/lib/posthog-server";

type RouteContext = { params: Promise<{ slug: string }> };

export async function GET(
  request: Request,
  { params }: RouteContext
) {
  const cfg = await getGlobalConfig<DecisionTracesConfig>("decision_traces");
  if (!cfg.enabled) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const [session, errorResponse] = await requireAuth(request);
  if (errorResponse) return errorResponse;

  const { slug } = await params;

  const rows = await db
    .select()
    .from(decisionTrace)
    .where(
      and(
        eq(decisionTrace.slug, slug),
        eq(decisionTrace.ownerId, session.user.id)
      )
    )
    .limit(1);

  const trace = rows[0];
  if (!trace) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  return NextResponse.json({
    trace: {
      id: trace.id,
      slug: trace.slug,
      question: trace.question,
      title: trace.title,
      projectPath: trace.projectPath,
      status: trace.status,
      content: trace.content,
      createdAt: trace.createdAt,
      updatedAt: trace.updatedAt,
    },
  });
}

export async function DELETE(
  request: Request,
  { params }: RouteContext
) {
  const [session, errorResponse] = await requireAuth(request);
  if (errorResponse) return errorResponse;

  const { slug } = await params;

  const deleted = await db
    .delete(decisionTrace)
    .where(
      and(
        eq(decisionTrace.slug, slug),
        eq(decisionTrace.ownerId, session.user.id)
      )
    )
    .returning({ status: decisionTrace.status });

  if (deleted[0]) {
    getPostHogClient().capture({
      distinctId: session.user.id,
      event: "trace_deleted",
      properties: {
        trace_slug: slug,
        status_at_delete: deleted[0].status,
      },
    });
  }

  return new Response(null, { status: 204 });
}

